// Quarterly check-in: who gets it, and the personalised email for each.
const RAF = 'rlakhani@anagomb.ca';
let scheduled = false;
try { scheduled = $('Every quarter, 9:00').isExecuted; } catch (e) {}
const test = !scheduled;
const now = DateTime.now().setZone('America/Winnipeg');
if (scheduled) {
  // run only on the first weekday of the quarter's first month
  if (now.weekday > 5) return [];
  for (let d = 1; d < now.day; d++) if (now.set({ day: d }).weekday <= 5) return [];
}
const quarter = now.year + 'Q' + Math.ceil(now.month / 3);
const optout = new Set($('Get opt-outs').all().map(i => String(i.json.email || '').toLowerCase().trim()).filter(Boolean));
const sent = new Set($('Get sent log').all().map(i => i.json.send_key).filter(Boolean));
const lost = $('Get lost deals').first().json.data || [];
const open = $('Get open deals').first().json.data || [];
const openPeople = new Set(open.map(d => d.person_id && d.person_id.value).filter(Boolean));
const openOrgs = new Set(open.map(d => d.org_id && d.org_id.value).filter(Boolean));
const F = 'font-family:Tahoma,Arial,Helvetica,sans-serif;font-size:10pt;color:#000';
const esc = s => String(s || '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const p = t => '<p style="' + F + ';margin:0 0 12px 0">' + t + '</p>';
// Letsignit signature copied with its marker, so Letsignit does not add a second one.
const sig = '<div style="' + F + ';margin-top:16px">Kind Regards,</div>'
  + '<p style="margin:0.1pt;text-align:left"></p><p style="margin:0cm;font-size:15px;font-family:&quot;Calibri&quot;,sans-serif">Raf Lakhani <br />Brand Manager | Anago of Manitoba<br />238 St Mary’s Road | Winnipeg, MB R2H 1J3<br />t+ 204.594.4666 |Direct+ 204.809.4347 | <a href="mailto:rlakhani@anagomb.ca">rlakhani@anagomb.ca</a></p><p style="margin:0cm;font-size:15px;font-family:&quot;Calibri&quot;,sans-serif"><a href="http://www.anagomb.ca/">www.AnagoMB.ca</a></p><p></p><table><tbody><tr><td><div id="LSI_marker" style="font-size:0px"> </div></td></tr></tbody></table>';
const seen = new Set();
const out = [];
for (const d of lost) {
  const person = d.person_id || {};
  const email = String(((person.email || []).find(e => e.primary) || (person.email || [])[0] || {}).value || '').toLowerCase().trim();
  if (!email || !/@/.test(email) || optout.has(email) || seen.has(email)) continue;
  if (/We're Not Pursuing|Bad Data|Do Not Call/i.test(d.lost_reason || '')) continue;
  if (openPeople.has(person.value) || (d.org_id && openOrgs.has(d.org_id.value))) continue;
  const lostAt = DateTime.fromISO(String(d.lost_time || d.update_time).replace(' ', 'T'), { zone: 'utc' });
  const ageDays = now.diff(lostAt, 'days').days;
  if (ageDays < 60 || ageDays > 3 * 365) continue;
  const key = quarter + ':' + email;
  if (sent.has(key)) continue;
  seen.add(email);
  const first = String(person.name || '').trim().split(/\s+/)[0] || 'there';
  const company = d.org_name || '';
  const street = esc(String((d.org_id && d.org_id.address) || '').split(',')[0].trim());
  const year = lostAt.toFormat('yyyy');
  const what = company ? esc(company) + (street ? ' at ' + street : '') : (street ? 'your space at ' + street : 'your space');
  const opener = d['1a6bd14374c1ccde3e2bea35879a917c6a9d8c11']
    ? 'In ' + year + ' we put together a cleaning proposal for ' + what + '.'
    : 'In ' + year + ' we spoke about cleaning for ' + what + '.';
  const r = d.lost_reason || '';
  let middle;
  if (/Other Service|Same Service|Canceled/i.test(r)) middle = 'You decided to stay with another provider at the time, and I hope it is working well. If anything has slipped, like missed areas, frequent staff changes or slow responses when something comes up, that is usually when businesses give us a second look.';
  else if (/Price/i.test(r)) middle = 'The price did not fit at the time. Budgets change, and so can the scope: we can adjust the frequency or focus on the high-traffic areas so the numbers work. I would be glad to rework the proposal around a budget you set.';
  else if (/In House/i.test(r)) middle = 'You were handling cleaning in-house at the time. If that has become more work than it is worth, we can take it off your team’s plate.';
  else middle = 'The timing was not right then, and that is completely fine. If anything has changed, like a contract coming up for renewal, a new space, or a cleaner who is not meeting expectations, I would be glad to help.';
  const offer = 'I can do a free 20-minute walkthrough and send you an updated quote within a couple of days. Just reply with a time that suits you, or call me directly at 204-809-4347.';
  const footer = '<p style="font-family:Tahoma,Arial,Helvetica,sans-serif;font-size:8pt;color:#808080;margin:12px 0 0 0">You are receiving this because you contacted Anago of Manitoba about cleaning' + (company ? ' for ' + esc(company) : '') + '. Reply “unsubscribe” and I will not email you again.</p>';
  const html = p('Hi ' + esc(first) + ',') + p(opener + ' ' + middle) + p(offer) + sig + footer;
  const subject = 'Quick check-in about cleaning' + (company ? ' at ' + company : '');
  out.push({ json: { live: !test, to: test ? RAF : email, subject: (test ? '[TEST to ' + email + '] ' : '') + subject, html, key, deal_id: d.id } });
  if (test && out.length >= 3) break;
}
return out;
